export function WorkAreaMap() {
  return (
    <svg
      viewBox="0 0 1000 553"
      role="img"
      aria-label="Kaart van Goeree-Overflakkee met de plaatsen waar wij werken"
      className="block h-auto w-full bg-navy-50"
    >
      <defs>
        <pattern
          id="sea"
          width="34"
          height="34"
          patternUnits="userSpaceOnUse"
        >
          <path
            d="M0 17 H34 M17 0 V34"
            stroke="#dee5ee"
            strokeWidth="1"
            fill="none"
          />
        </pattern>
      </defs>

      {/* Water + subtiel raster */}
      <rect width="1000" height="553" fill="#f1f4f8" />
      <rect width="1000" height="553" fill="url(#sea)" />

      {/* Het eiland - gehighlight */}
      <path
        d={ISLAND_PATH}
        fill="#142a47"
        stroke="#0c2340"
        strokeWidth="2"
        strokeLinejoin="round"
        paintOrder="stroke"
      />
      {/* Subtiele binnenlijn voor diepte */}
      <path
        d={ISLAND_PATH}
        fill="none"
        stroke="#ffffff"
        strokeOpacity="0.12"
        strokeWidth="6"
        strokeLinejoin="round"
      />

      {/* Plaatsen */}
      {TOWNS.map((t) => (
        <g key={t.name}>
          {t.primary && (
            <circle
              cx={t.x}
              cy={t.y}
              r="13"
              fill="#ffffff"
              fillOpacity="0.18"
            />
          )}
          <circle
            cx={t.x}
            cy={t.y}
            r={t.primary ? 6.5 : 4.5}
            fill="#ffffff"
            stroke="#0c2340"
            strokeWidth={t.primary ? 3 : 2}
          />
          <text
            x={t.x}
            y={t.y}
            dy={t.dy}
            textAnchor={t.anchor}
            className="fill-white"
            style={{
              fontSize: t.primary ? 22 : 19,
              fontWeight: t.primary ? 700 : 500,
              paintOrder: "stroke",
            }}
            stroke="#0c2340"
            strokeWidth="4"
            strokeLinejoin="round"
          >
            {t.name}
          </text>
        </g>
      ))}
    </svg>
  );
}
